"use client";

import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useEffect, useRef, useState } from "react";
import type { UnifiedScrollHandle } from "@/lib/toolkit/scroll";
import { createUnifiedScroll } from "@/lib/toolkit/scroll";
import type { AirplaneScene } from "./hooks/useAirplaneScene";
import { useAirplaneScene } from "./hooks/useAirplaneScene";
import { BlueprintSection } from "./sections/BlueprintSection";
import { EndSection } from "./sections/EndSection";
import { HeroSection } from "./sections/HeroSection";
import { NarrativeSection } from "./sections/NarrativeSection";
import "./styles.css";
import { buildFlightTimeline } from "./timeline";

gsap.registerPlugin(ScrollTrigger);

export default function Airplanes() {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<UnifiedScrollHandle | null>(null);
  const [scene, setScene] = useState<AirplaneScene | null>(null);
  const { init } = useAirplaneScene();

  useEffect(() => {
    scrollRef.current = createUnifiedScroll();
    ScrollTrigger.refresh();
    return () => scrollRef.current?.destroy();
  }, []);

  useEffect(() => {
    if (!containerRef.current) {
      return;
    }

    let cancelled = false;
    const container = containerRef.current;

    init(container).then((s) => {
      if (!cancelled && s) {
        setScene(s);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [init]);

  useGSAP(
    () => {
      if (scene) {
        buildFlightTimeline(scene);
      }
    },
    { scope: containerRef, dependencies: [scene] }
  );

  return (
    <div className="airplanes-root" ref={containerRef}>
      <div className="airplanes-loading">Loading</div>
      <div className="airplanes-content">
        <HeroSection />
        <NarrativeSection />
        <BlueprintSection />
        <EndSection />
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef } from "react";
import type {
  Group,
  LineBasicMaterial,
  Material,
  Mesh,
  Object3D,
  PerspectiveCamera,
  PointLight,
  Scene,
  WebGLRenderer,
} from "three";
import {
  ASSET_BASE,
  INITIAL_CAMERA_Z,
  LIGHT_CONFIG,
  MODEL_MATERIAL,
} from "../data";

interface View {
  bottom: number;
  camera: PerspectiveCamera | null;
  height: number;
}

export interface AirplaneScene {
  destroy: () => void;
  light: PointLight;
  modelGroup: Group;
  render: () => void;
  views: View[];
}

// ── Dynamic imports ──

async function loadDeps() {
  const [three, objModule] = await Promise.all([
    import("three"),
    import("three/addons/loaders/OBJLoader.js"),
  ]);
  return { three, OBJLoader: objModule.OBJLoader };
}

// ── Scene construction helpers ──

function createRenderer(
  three: typeof import("three"),
  container: HTMLElement
): WebGLRenderer {
  const renderer = new three.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = three.PCFSoftShadowMap;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.domElement.classList.add("airplanes-canvas");
  container.appendChild(renderer.domElement);
  return renderer;
}

function createViewCameras(three: typeof import("three")): View[] {
  const views: View[] = [
    { bottom: 0, height: 1, camera: null },
    { bottom: 0, height: 0, camera: null },
  ];

  for (let i = 0; i < views.length; i++) {
    const camera = new three.PerspectiveCamera(
      45,
      window.innerWidth / window.innerHeight,
      1,
      2000
    );
    camera.position.set(0, 0, INITIAL_CAMERA_Z);
    camera.layers.disableAll();
    camera.layers.enable(i);
    camera.lookAt(new three.Vector3(0, 5, 0));
    views[i].camera = camera;
  }

  return views;
}

function createLighting(
  three: typeof import("three"),
  scene: Scene
): PointLight {
  const light = new three.PointLight(
    LIGHT_CONFIG.point.color,
    LIGHT_CONFIG.point.intensity
  );
  light.position.set(
    LIGHT_CONFIG.point.position.x,
    LIGHT_CONFIG.point.position.y,
    LIGHT_CONFIG.point.position.z
  );
  scene.add(light);

  const ambient = new three.AmbientLight(
    LIGHT_CONFIG.ambient.color,
    LIGHT_CONFIG.ambient.intensity
  );
  scene.add(ambient);

  return light;
}

function createModelGroup(
  three: typeof import("three"),
  model: Object3D
): Group {
  const firstChild = model.children[0] as Mesh | undefined;
  if (!firstChild?.geometry) {
    throw new Error("Model has no valid geometry");
  }

  const edges = new three.EdgesGeometry(firstChild.geometry);
  const line = new three.LineSegments(edges);

  const mat = line.material as LineBasicMaterial;
  mat.depthTest = false;
  mat.opacity = 0.5;
  mat.transparent = true;

  line.position.set(0.5, 0.2, -1);

  const group = new three.Group();
  model.layers.set(0);
  line.layers.set(1);
  group.add(model);
  group.add(line);

  return group;
}

// ── Scene assembly ──

function createScene(
  three: typeof import("three"),
  model: Object3D,
  container: HTMLElement
): AirplaneScene {
  const renderer = createRenderer(three, container);
  const views = createViewCameras(three);
  const scene = new three.Scene();
  const light = createLighting(three, scene);
  const modelGroup = createModelGroup(three, model);
  scene.add(modelGroup);

  let w = window.innerWidth;
  let h = window.innerHeight;

  const render = () => {
    for (const view of views) {
      if (!view.camera) {
        continue;
      }
      const bottom = Math.floor(h * view.bottom);
      const height = Math.floor(h * view.height);
      renderer.setViewport(0, 0, w, h);
      renderer.setScissor(0, bottom, w, height);
      renderer.setScissorTest(true);
      renderer.render(scene, view.camera);
    }
  };

  const onResize = () => {
    w = window.innerWidth;
    h = window.innerHeight;
    for (const view of views) {
      if (!view.camera) {
        continue;
      }
      view.camera.aspect = w / h;
      // Adaptive zoom: when the browser is narrower than the physical screen,
      // push the camera back proportionally so the model stays visible.
      const camZ = (screen.width - w) / 3;
      view.camera.position.z =
        camZ < INITIAL_CAMERA_Z ? INITIAL_CAMERA_Z : camZ;
      view.camera.updateProjectionMatrix();
    }
    renderer.setSize(w, h);
    render();
  };

  window.addEventListener("resize", onResize);
  onResize();

  const destroy = () => {
    window.removeEventListener("resize", onResize);
    renderer.dispose();
    renderer.domElement.remove();
    scene.traverse((obj) => {
      const mesh = obj as Mesh;
      if (mesh.geometry) {
        mesh.geometry.dispose();
      }
      if (mesh.material) {
        if (Array.isArray(mesh.material)) {
          mesh.material.forEach((m: Material) => m.dispose());
        } else {
          (mesh.material as Material).dispose();
        }
      }
    });
  };

  return { modelGroup, render, views, light, destroy };
}

// ── Model loading ──

async function loadModel() {
  const { three, OBJLoader } = await loadDeps();

  const model: Object3D = await new Promise((resolve, reject) => {
    const loader = new OBJLoader();
    loader.load(
      `${ASSET_BASE}/plane.obj`,
      (obj) => {
        obj.traverse((child) => {
          const mesh = child as Mesh;
          if (mesh.isMesh) {
            mesh.material = new three.MeshPhongMaterial({
              color: MODEL_MATERIAL.color,
              specular: MODEL_MATERIAL.specular,
              shininess: MODEL_MATERIAL.shininess,
              flatShading: true,
            });
          }
        });
        resolve(obj);
      },
      undefined,
      reject
    );
  });

  return { three, model };
}

// ── Hook ──

export function useAirplaneScene() {
  const sceneRef = useRef<AirplaneScene | null>(null);
  const readyRef = useRef(false);

  const init = useCallback(
    async (container: HTMLElement): Promise<AirplaneScene | null> => {
      if (readyRef.current) {
        return sceneRef.current;
      }
      const { three, model } = await loadModel();
      const airplaneScene = createScene(three, model, container);
      sceneRef.current = airplaneScene;
      readyRef.current = true;
      return airplaneScene;
    },
    []
  );

  useEffect(() => {
    return () => {
      sceneRef.current?.destroy();
      sceneRef.current = null;
      readyRef.current = false;
    };
  }, []);

  return { init };
}

import { END } from "../data";

export function EndSection() {
  return (
    <div className="airplanes-sunset">
      <section className="airplanes-section airplanes-end">
        <h2>{END.title}</h2>
        <ul className="airplanes-credits">
          {END.credits.map((credit, i) => (
            <li key={i}>
              {credit.text}{" "}
              <a
                href={credit.link.href}
                rel="noopener noreferrer"
                target="_blank"
              >
                {credit.link.label}
              </a>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

import { HERO } from "../data";

export function HeroSection() {
  return (
    <div className="airplanes-ground-container">
      <div className="airplanes-parallax airplanes-ground" />
      <div className="airplanes-parallax airplanes-clouds" />
      <section className="airplanes-section">
        <h1>{HERO.title}</h1>
        <h3>{HERO.subtitle}</h3>
        <p>{HERO.description}</p>
        <p className="airplanes-scroll-cta">{HERO.scrollCta}</p>
      </section>
    </div>
  );
}

import { NARRATIVE_SECTIONS } from "../data";

export function NarrativeSection() {
  return (
    <>
      {NARRATIVE_SECTIONS.map((section, i) => (
        <section
          className={`airplanes-section dark ${section.align === "right" ? "right" : ""}`}
          key={i}
        >
          {section.lines.map((line, j) =>
            j === 0 ? <h2 key={j}>{line}</h2> : <h3 key={j}>{line}</h3>
          )}
        </section>
      ))}
    </>
  );
}

import gsap from "gsap";
import {
  BLUEPRINT_HOLD_INDEX,
  PLANE_KEYFRAMES,
  SECTION_DURATION,
} from "./data";
import type { AirplaneScene } from "./hooks/useAirplaneScene";

/**
 * Build all scroll-driven GSAP animations for the airplane experiment.
 * Pure side-effect function -- creates ScrollTriggers scoped to the container
 * that useGSAP will clean up automatically.
 */
export function buildFlightTimeline(scene: AirplaneScene): void {
  const plane = scene.modelGroup;
  const kf = PLANE_KEYFRAMES;

  // ── Intro tweens ──
  gsap.fromTo(
    "canvas.airplanes-canvas",
    { x: "50%", autoAlpha: 0 },
    { duration: 1, x: "0%", autoAlpha: 1 }
  );
  gsap.to(".airplanes-loading", { autoAlpha: 0 });
  gsap.to(".airplanes-scroll-cta", { opacity: 1 });
  gsap.set(".airplanes-blueprint svg", { autoAlpha: 1 });

  // ── Initial pose ──
  gsap.set(plane.rotation, kf[0].rotation);
  gsap.set(plane.position, kf[0].position);
  scene.render();

  // ── Blueprint viewport transitions (wireframe reveal / exit) ──
  gsap.fromTo(
    scene.views[1],
    { height: 0, bottom: 0 },
    {
      height: 1,
      bottom: 0,
      ease: "none",
      scrollTrigger: {
        trigger: ".airplanes-blueprint",
        scrub: true,
        start: "top bottom",
        end: "top top",
      },
    }
  );

  gsap.fromTo(
    scene.views[1],
    { height: 1, bottom: 0 },
    {
      height: 0,
      bottom: 1,
      ease: "none",
      scrollTrigger: {
        trigger: ".airplanes-blueprint",
        scrub: true,
        start: "bottom bottom",
        end: "bottom top",
      },
    }
  );

  // ── Parallax layers ──
  gsap.to(".airplanes-ground", {
    y: "30%",
    scrollTrigger: {
      trigger: ".airplanes-ground-container",
      scrub: true,
      start: "top bottom",
      end: "bottom top",
    },
  });

  gsap.from(".airplanes-clouds", {
    y: "25%",
    scrollTrigger: {
      trigger: ".airplanes-ground-container",
      scrub: true,
      start: "top bottom",
      end: "bottom top",
    },
  });

  // ── SVG line-drawing annotations ──
  setupSvgDraw("#line-length", ".length");
  setupSvgDraw("#line-wingspan", ".wingspan", "top 25%", "bottom 50%");
  setupSvgDraw("#circle-phalange", ".phalange", "top 50%", "bottom 100%");

  // ── Master flight timeline ──
  const tl = gsap.timeline({
    onUpdate: scene.render,
    scrollTrigger: {
      trigger: ".airplanes-content",
      scrub: true,
      start: "top top",
      end: "bottom bottom",
    },
    defaults: { duration: SECTION_DURATION, ease: "power2.inOut" },
  });

  let delay = 0;
  tl.to(".airplanes-scroll-cta", { duration: 0.25, opacity: 0 }, delay);
  tl.to(plane.position, { x: kf[1].position.x, ease: "power1.in" }, delay);

  for (let i = 2; i < kf.length; i++) {
    delay += SECTION_DURATION;

    if (i === BLUEPRINT_HOLD_INDEX) {
      delay += SECTION_DURATION;
      continue;
    }

    const frame = kf[i];
    const rotEase = frame.ease ?? "power2.inOut";
    const posEase = frame.positionEase ?? rotEase;
    const isLast = i === kf.length - 1;

    tl.to(
      plane.rotation,
      {
        ...frame.rotation,
        ease: rotEase,
        ...(isLast ? { duration: SECTION_DURATION } : {}),
      },
      delay
    );

    tl.to(
      plane.position,
      {
        ...frame.position,
        ease: posEase,
        ...(isLast ? { duration: SECTION_DURATION } : {}),
      },
      delay
    );
  }

  tl.to(
    scene.light.position,
    { duration: SECTION_DURATION, x: 0, y: 0, z: 0 },
    delay
  );
}

function setupSvgDraw(
  selector: string,
  trigger: string,
  start = "top bottom",
  end = "top top"
) {
  const el = document.querySelector<SVGGeometryElement>(selector);
  if (!el) {
    return;
  }

  const length = el.getTotalLength();
  gsap.set(el, { strokeDasharray: length, strokeDashoffset: length });

  gsap.to(el, {
    strokeDashoffset: 0,
    scrollTrigger: { trigger, scrub: true, start, end },
  });

  gsap.to(el, {
    opacity: 0,
    strokeDashoffset: length,
    scrollTrigger: {
      trigger,
      scrub: true,
      start: "top top",
      end: "bottom top",
    },
  });
}

export const ASSET_BASE = "https://www.razisyed.cv/experiments/airplanes";

export const HERO = {
  title: "Airplanes.",
  subtitle: "The beginners guide.",
  description: "You've probably forgotten what these are.",
  scrollCta: "Scroll",
} as const;

export const NARRATIVE_SECTIONS = [
  {
    lines: ["They're kinda like buses..."],
    align: "left" as const,
  },
  {
    lines: ["..except they leave the ground.", "Saaay what!?."],
    align: "right" as const,
  },
  {
    lines: ["They fly through the sky.", "For realsies!"],
    align: "left" as const,
  },
  {
    lines: ["Defying all known physical laws.", "It's actual magic!"],
    align: "right" as const,
  },
] as const;

export const BLUEPRINT_FACTS = [
  { label: "Length.", value: "Long.", className: "length" },
  {
    label: "Wing Span.",
    value: "I dunno, longer than a cat probably.",
    className: "wingspan",
  },
  { label: "Left Phalange", value: "Missing", className: "phalange" },
  { label: "Engines", value: "Turbine funtime", className: "" },
] as const;

export const END = {
  title: "Fin.",
  credits: [
    {
      text: "Plane model by",
      link: {
        label: "Google",
        href: "https://poly.google.com/view/8VysVzMlBtk",
      },
    },
    {
      text: "Animated using",
      link: {
        label: "GSAP ScrollTrigger",
        href: "https://greensock.com/scrolltrigger",
      },
    },
  ],
} as const;

const TAU = Math.PI * 2;

export interface PlaneKeyframe {
  ease?: string;
  position: { x: number; y: number; z: number };
  positionEase?: string;
  rotation: { x: number; y: number; z: number };
}

export const SECTION_DURATION = 1;

export const BLUEPRINT_HOLD_INDEX = 6;

export const PLANE_KEYFRAMES: PlaneKeyframe[] = [
  // 0: Initial (set, not tweened)
  {
    position: { x: 80, y: -32, z: -60 },
    rotation: { x: 0, y: TAU * -0.25, z: 0 },
  },
  // 1: Slide in from right
  {
    position: { x: -10, y: -32, z: -60 },
    rotation: { x: 0, y: TAU * -0.25, z: 0 },
    positionEase: "power1.in",
  },
  // 2: Bank left
  {
    position: { x: -40, y: 0, z: -60 },
    rotation: { x: TAU * 0.25, y: 0, z: -TAU * 0.05 },
    ease: "power1.inOut",
  },
  // 3: Bank right
  {
    position: { x: 40, y: 0, z: -60 },
    rotation: { x: TAU * 0.25, y: 0, z: TAU * 0.05 },
    ease: "power3.inOut",
    positionEase: "power2.inOut",
  },
  // 4: Swoop left
  {
    position: { x: -40, y: 0, z: -30 },
    rotation: { x: TAU * 0.2, y: 0, z: -TAU * 0.1 },
    ease: "power3.inOut",
    positionEase: "power2.inOut",
  },
  // 5: Face camera
  {
    position: { x: 0, y: -10, z: 50 },
    rotation: { x: 0, y: TAU * 0.25, z: 0 },
  },
  // 6: (blueprint section hold - same as 5)
  {
    position: { x: 0, y: -10, z: 50 },
    rotation: { x: 0, y: TAU * 0.25, z: 0 },
  },
  // 7: Rotate toward viewer
  {
    position: { x: 0, y: -10, z: 30 },
    rotation: { x: TAU * 0.25, y: TAU * 0.5, z: 0 },
    ease: "power4.inOut",
  },
  // 8: Slide right
  {
    position: { x: 30, y: -10, z: 60 },
    rotation: { x: TAU * 0.25, y: TAU * 0.5, z: 0 },
    ease: "power4.inOut",
  },
  // 9: Tumble
  {
    position: { x: 20, y: 0, z: 100 },
    rotation: { x: TAU * 0.35, y: TAU * 0.75, z: TAU * 0.6 },
    ease: "power4.inOut",
  },
  // 10: Pull away
  {
    position: { x: 0, y: 0, z: -150 },
    rotation: { x: TAU * 0.15, y: TAU * 0.85, z: 0 },
    ease: "power1.in",
    positionEase: "power1.inOut",
  },
  // 11: Fly over camera
  {
    position: { x: 0, y: 30, z: 320 },
    rotation: { x: -TAU * 0.05, y: TAU, z: -TAU * 0.1 },
    ease: "none",
    positionEase: "power1.in",
  },
];

export const MODEL_MATERIAL = {
  color: 0x17_15_11,
  specular: 0xd0_cb_c7,
  shininess: 5,
} as const;

export const INITIAL_CAMERA_Z = 180;

export const LIGHT_CONFIG = {
  point: {
    color: 0xff_ff_ff,
    intensity: 0.75,
    position: { x: 70, y: -20, z: 150 },
  },
  ambient: { color: 0xff_ff_ff, intensity: 1.5 },
} as const;
